   const t=i/countSteps,point=segment(bat.grip,bat.tip,t),pr=project(point);
   if(!pr||pr.x<gridV84.step()||pr.x>(600-gridV84.step())||pr.y<gridV84.step()||pr.y>(432-gridV84.step()))continue;
